(850145, 96456, 19978, '<td valign="top">Excellent! I love the creativity. The composition and technical qualities are outstanding!</td>', 'Excellent! I love the creativity. The composition and technical qualities are outstanding!', '2004-08-09 02:18:58.000000', NULL, 1),
