(851708, 95828, 327, '<td valign="top">Nice, 9</td>', 'Nice, 9', '2004-08-09 22:15:47.000000', NULL, 1),
(851710, 95650, 11653, '<td valign="top">Subject too much in the center, nice detail. I would suggest croping some off the left and the bottom</td>', 'Subject too much in the center, nice detail. I would suggest croping some off the left and the bottom', '2004-08-09 22:16:00.000000', NULL, 1),
(851711, 96596, 327, '<td valign="top">9 Bravo. Love the tones.</td>', '9 Bravo. Love the tones.', '2004-08-09 22:16:05.000000', NULL, 1),
(851716, 95588, 11653, '<td valign="top">main subject is the frog not the feet</td>', 'main subject is the frog not the feet', '2004-08-09 22:20:07.000000', NULL, 1),
(851722, 95630, 25033, '<td valign="top">I LOVE LOVE LOVE LOVE THIS!!  10</td>', 'I LOVE LOVE LOVE LOVE THIS!!  10', '2004-08-09 22:30:11.000000', NULL, 1),
(851727, 96556, 7628, '<td valign="top">Fabulous color and texture - fun composition!  10</td>', 'Fabulous color and texture - fun composition!  10', '2004-08-09 22:37:44.000000', NULL, 1),
(851736, 96314, 7628, '<td valign="top">Very Film Noir lighting - good effect and appropriate here. I like the slightly off-kilter composition.  The feet just look too smooth - neat image?</td>', 'Very Film Noir lighting - good effect and appropriate here. I like the slightly off-kilter composition.  The feet just look too smooth - neat image?', '2004-08-09 22:51:50.000000', NULL, 1),
(851741, 95368, 7628, '<td valign="top">What I particularly like is the motion in the foot stepping down - when everything else is very solid and still.  It is this subtle motion and the simple, elegant balance between the dark and the light that make this photo a stand out.  10</td>', 'What I particularly like is the motion in the foot stepping down - when everything else is very solid and still.  It is this subtle motion and the simple, elegant balance between the dark and the light that make this photo a stand out.  10', '2004-08-09 22:54:14.000000', NULL, 1),
(851744, 96608, 7628, '<td valign="top">This is a sweet composition of nostalgic childhood - catching that weightless moment in the swing with our feet free and flying - and the background of the white fence and trees and neat lawn are all in the same flavor, all the same theme.  I like the sepia tone as well.  I wish we could see the face just a bit better. 9</td>', 'This is a sweet composition of nostalgic childhood - catching that weightless moment in the swing with our feet free and flying - and the background of the white fence and trees and neat lawn are all in the same flavor, all the same theme.  I like the sepia tone as well.  I wish we could see the face just a bit better. 9', '2004-08-09 22:56:54.000000', NULL, 1),
(851745, 96512, 7628, '<td valign="top">Gloriously composed and crafted - all those hairy details in the flower and the bee!  The feet are''nt the stand out part of the image - but who cares? 9</td>', 'Gloriously composed and crafted - all those hairy details in the flower and the bee!  The feet are''nt the stand out part of the image - but who cares? 9', '2004-08-09 22:58:12.000000', NULL, 1),
(851749, 96567, 7628, '<td valign="top">This is dynamic - a good captured moment of action and a daring composition.  I wish the legs and feet came just a bit more into the frame - but I like all the open green space it works well with the sense of action and movement - keeps the viewer in mind of what the next moment willl bring. 7</td>', 'This is dynamic - a good captured moment of action and a daring composition.  I wish the legs and feet came just a bit more into the frame - but I like all the open green space it works well with the sense of action and movement - keeps the viewer in mind of what the next moment willl bring. 7', '2004-08-09 23:00:30.000000', NULL, 1),
(851752, 96505, 3697, '<td valign="top">Great shot, it''s definately one of the week''s best.</td>', 'Great shot, it''s definately one of the week''s best.', '2004-08-09 23:01:00.000000', NULL, 1),
(851755, 96601, 3697, '<td valign="top">Great composition and cropping, it instantly made me think of Tom Sawyer.</td>', 'Great composition and cropping, it instantly made me think of Tom Sawyer.', '2004-08-09 23:02:01.000000', NULL, 1),
(851756, 96314, 3697, '<td valign="top">Very good composition and great work on the black and white treatment. Like they say, dead feet are still feet :)</td>', 'Very good composition and great work on the black and white treatment. Like they say, dead feet are still feet :)', '2004-08-09 23:02:47.000000', NULL, 1),
(851757, 96581, 3697, '<td valign="top">I love it! Great photoshop work, without going overboard. One of the week''s best.</td>', 'I love it! Great photoshop work, without going overboard. One of the week''s best.', '2004-08-09 23:05:06.000000', NULL, 1),
(851762, 95589, 25216, '<td valign="top">Wow, this is a cool shoot, Unique angle.</td>', 'Wow, this is a cool shoot, Unique angle.', '2004-08-09 23:08:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(851765, 96063, 23680, '<td valign="top">Great shot - one of my favorites even though you can''t see the whole foot ;)</td>', 'Great shot - one of my favorites even though you can''t see the whole foot ;)', '2004-08-09 23:10:11.000000', NULL, 1),
(851766, 96328, 23680, '<td valign="top">A little busy, all the wires (not your fault of course) detract from the feet</td>', 'A little busy, all the wires (not your fault of course) detract from the feet', '2004-08-09 23:10:55.000000', NULL, 1),
(851769, 96583, 23680, '<td valign="top">Cute - I like the concept</td>', 'Cute - I like the concept', '2004-08-09 23:13:32.000000', NULL, 1),
(851771, 96492, 23680, '<td valign="top">Funny :)</td>', 'Funny :)', '2004-08-09 23:13:43.000000', NULL, 1),
(851793, 96545, 14620, '<td valign="top">Great lighting, love the shadows!  Very nice, pleasing composition.</td>', 'Great lighting, love the shadows!  Very nice, pleasing composition.', '2004-08-09 23:29:42.000000', NULL, 1),
(851794, 96510, 14620, '<td valign="top">Super sweet shot!!  I like the muted desaturated treatment and the detail of the grass below their feet.  Very nice.</td>', 'Super sweet shot!!  I like the muted desaturated treatment and the detail of the grass below their feet.  Very nice.', '2004-08-09 23:31:06.000000', NULL, 1),
(851800, 96305, 14620, '<td valign="top">AWWwwww, these are the cutest little feet.  Great composition, I love the little crossed feet and the raised toe.  Also like the use of the texture in the stairs.</td>', 'AWWwwww, these are the cutest little feet.  Great composition, I love the little crossed feet and the raised toe.  Also like the use of the texture in the stairs.', '2004-08-09 23:33:12.000000', NULL, 1),
(851802, 96211, 14620, '<td valign="top">I really love your choice of lighting and the color treatment.  Very nice.  My only thoughts on a change would be to have the very back foot a little more in focus.  As it is, it looks a little odd, might help to have the toes just a little more defined.  But overall, I think the composition is great and again the color treatment is top notch!</td>', 'I really love your choice of lighting and the color treatment.  Very nice.  My only thoughts on a change would be to have the very back foot a little more in focus.  As it is, it looks a little odd, might help to have the toes just a little more defined.  But overall, I think the composition is great and again the color treatment is top notch!', '2004-08-09 23:36:27.000000', NULL, 1),
(851803, 96457, 14620, '<td valign="top">What a unique treatment.  I quite like it.  I like how the box is tilted to almost match the edge of the table cloth and that the pertinent part of the shot is in color and focused.  Nice creative shot with a pleasing composition.</td>', 'What a unique treatment.  I quite like it.  I like how the box is tilted to almost match the edge of the table cloth and that the pertinent part of the shot is in color and focused.  Nice creative shot with a pleasing composition.', '2004-08-09 23:38:46.000000', NULL, 1),
(851807, 96501, 14620, '<td valign="top">What interesting faucets, never seen two in a tub!  :) as for the picture, great composition, I especially like the clean light colors of the shot, bright yet somewhat muted.  Very nice</td>', 'What interesting faucets, never seen two in a tub!  :) as for the picture, great composition, I especially like the clean light colors of the shot, bright yet somewhat muted.  Very nice', '2004-08-09 23:41:51.000000', NULL, 1),
(851821, 96505, 22975, '<td valign="top">This is awesome.  This would make a great image ad for a shoe company... or a kick-ass label for Jones Soda!  You should enter it-- www.jonessoda.com!  :)  10</td>', 'This is awesome.  This would make a great image ad for a shoe company... or a kick-ass label for Jones Soda!  You should enter it-- www.jonessoda.com!  :)  10', '2004-08-09 23:57:26.000000', NULL, 1),
(851841, 96526, 21072, '<td valign="top">Good shot, it is interesting, and has a story ... I am assuming that the person is running towards the life saver thing because someone is in the water??  However, it looks a little like the person could be  just standing and raising a leg instead of running though, because I can''t see much movement in the picture.  When you run there is usually sand flying around near your feet.  Goodluck.</td>', 'Good shot, it is interesting, and has a story ... I am assuming that the person is running towards the life saver thing because someone is in the water??  However, it looks a little like the person could be  just standing and raising a leg instead of running though, because I can''t see much movement in the picture.  When you run there is usually sand flying around near your feet.  Goodluck.', '2004-08-10 00:20:26.000000', NULL, 1),
(851843, 96459, 21072, '<td valign="top">Feet are clearly not the main subject of this photo...</td>', 'Feet are clearly not the main subject of this photo...', '2004-08-10 00:21:59.000000', NULL, 1),
(851844, 96594, 18933, '<td valign="top">interesting ....  makes me wonder</td>', 'interesting ....  makes me wonder', '2004-08-10 00:22:46.000000', NULL, 1),
(851861, 96109, 18933, '<td valign="top">very dreamy shot - let''s the viewer put emotopm in the picture</td>', 'very dreamy shot - let''s the viewer put emotopm in the picture', '2004-08-10 00:38:07.000000', NULL, 1),
(851884, 96064, 20115, '<td valign="top">Love pigs--hate this--makes me sad.  Maybe if more people saw it they would stop eating pigs.</td>', 'Love pigs--hate this--makes me sad.  Maybe if more people saw it they would stop eating pigs.', '2004-08-10 00:55:06.000000', NULL, 1),
