(851940, 96452, 21072, '<td valign="top">Nice picture. I think showing a bit more of the feet would improve it a bit.</td>', 'Nice picture. I think showing a bit more of the feet would improve it a bit.', '2004-08-10 01:44:59.000000', NULL, 1),
(851943, 95828, 21072, '<td valign="top">Great picture ... but makes me feel a bit queasy, being dead feet and all.</td>', 'Great picture ... but makes me feel a bit queasy, being dead feet and all.', '2004-08-10 01:46:24.000000', NULL, 1),
(851949, 96374, 21072, '<td valign="top">very creative...</td>', 'very creative...', '2004-08-10 01:48:00.000000', NULL, 1),
