(851961, 95556, 21072, '<td valign="top">Image is very small...</td>', 'Image is very small...', '2004-08-10 01:52:53.000000', NULL, 1),
(851968, 96601, 21072, '<td valign="top">I really like this photo alot.  The composition, b/w, and so on are good.... (There is a bright distracting spot in between the trees in the backgroung though).  Well done, and goodluck :-)</td>', 'I really like this photo alot.  The composition, b/w, and so on are good.... (There is a bright distracting spot in between the trees in the backgroung though).  Well done, and goodluck :-)', '2004-08-10 01:58:29.000000', NULL, 1),
(851978, 96449, 21072, '<td valign="top">Good picture, but should make the photo bigger.  Cropping some from the top would look better (from my point of view anyway).  Goodluck.</td>', 'Good picture, but should make the photo bigger.  Cropping some from the top would look better (from my point of view anyway).  Goodluck.', '2004-08-10 02:04:49.000000', NULL, 1),
