(852016, 96460, 21072, '<td valign="top">Great idea and photo.</td>', 'Great idea and photo.', '2004-08-10 02:28:08.000000', NULL, 1),
(852017, 96582, 21072, '<td valign="top">Ha, this shot is cool ... goodluck :-)</td>', 'Ha, this shot is cool ... goodluck :-)', '2004-08-10 02:29:09.000000', NULL, 1),
(852018, 96526, 3294, '<td valign="top">Not sure you you did it, but the photo has a lot of movement... I like the way my eye moves from bottom left to top right.  The little piece of color is an interesting addition... my favorite of the challenge.</td>', 'Not sure you you did it, but the photo has a lot of movement... I like the way my eye moves from bottom left to top right.  The little piece of color is an interesting addition... my favorite of the challenge.', '2004-08-10 02:29:48.000000', NULL, 1),
(852020, 96569, 21072, '<td valign="top">Nice photo, but I don''t understand why the wood was left, and the sand desaturated.</td>', 'Nice photo, but I don''t understand why the wood was left, and the sand desaturated.', '2004-08-10 02:31:40.000000', NULL, 1),
(852021, 96599, 6817, '<td valign="top">Interesting...not sure if it''s painted or what? But it works.</td>', 'Interesting...not sure if it''s painted or what? But it works.', '2004-08-10 02:31:53.000000', NULL, 1),
(852023, 96430, 21072, '<td valign="top">I like this shot, but I do think the pink is too bright (glarey?)</td>', 'I like this shot, but I do think the pink is too bright (glarey?)', '2004-08-10 02:33:27.000000', NULL, 1),
(852025, 96604, 6817, '<td valign="top">Interesting...something about the lone bare walls and the single light, kind of old timey. I wish it were a little bit less fuzzy though. Keeps a 8 to a 6</td>', 'Interesting...something about the lone bare walls and the single light, kind of old timey. I wish it were a little bit less fuzzy though. Keeps a 8 to a 6', '2004-08-10 02:35:05.000000', NULL, 1),
(852026, 96457, 21072, '<td valign="top">This is very clever and well done.  Goodluck :-)</td>', 'This is very clever and well done.  Goodluck :-)', '2004-08-10 02:35:55.000000', NULL, 1),
(852027, 96456, 6817, '<td valign="top">Good. I was wondering if anyone would think of this. Nicely photographed.</td>', 'Good. I was wondering if anyone would think of this. Nicely photographed.', '2004-08-10 02:36:09.000000', NULL, 1),
(852028, 95995, 21072, '<td valign="top">Attack of the giants!!!   Nice shot.</td>', 'Attack of the giants!!!   Nice shot.', '2004-08-10 02:37:39.000000', NULL, 1),
(852029, 96457, 6817, '<td valign="top">Very nice display on an old idea. Nice image. Thanks for using attractive feet. 10</td>', 'Very nice display on an old idea. Nice image. Thanks for using attractive feet. 10', '2004-08-10 02:38:11.000000', NULL, 1),
(852031, 96557, 21072, '<td valign="top">With a different background, I think what you are trying to convey would come across better.</td>', 'With a different background, I think what you are trying to convey would come across better.', '2004-08-10 02:38:54.000000', NULL, 1),
(852032, 95589, 21072, '<td valign="top">This looks really cool ... well done!</td>', 'This looks really cool ... well done!', '2004-08-10 02:39:50.000000', NULL, 1),
(852033, 96116, 6817, '<td valign="top">Great idea!!! Excellent capture of color, but I''m a little caught up in the very nice capture of colors so I think I might have liked this better in B&amp;W. But still a 9</td>', 'Great idea!!! Excellent capture of color, but I''m a little caught up in the very nice capture of colors so I think I might have liked this better in B&W. But still a 9', '2004-08-10 02:41:06.000000', NULL, 1),
(852035, 96593, 21072, '<td valign="top">Different interpretations are always good.</td>', 'Different interpretations are always good.', '2004-08-10 02:43:58.000000', NULL, 1),
(852090, 96383, 20613, '<td valign="top">I don''t really feel like the subject of this photo is feet.  It seems very "snapshoty" to me.</td>', 'I don''t really feel like the subject of this photo is feet.  It seems very "snapshoty" to me.', '2004-08-10 04:05:07.000000', NULL, 1),
(852091, 96291, 20613, '<td valign="top">Great title, and very interesting photograph... great way to photograph a foot without having an actual foot in the shot.  I really do think feet are ugly, so this is quite pleasant to my eyes.  Great colors &amp; great focus.  amazing job!</td>', 'Great title, and very interesting photograph... great way to photograph a foot without having an actual foot in the shot.  I really do think feet are ugly, so this is quite pleasant to my eyes.  Great colors & great focus.  amazing job!', '2004-08-10 04:05:56.000000', NULL, 1),
(852092, 96585, 20613, '<td valign="top">Nice shot, I like the shadows &amp; the composition.  I''m not crazy about the border.</td>', 'Nice shot, I like the shadows & the composition.  I''m not crazy about the border.', '2004-08-10 04:07:34.000000', NULL, 1),
(852109, 96457, 10170, '<td valign="top">Excellent photo in general, but I especially like what you''ve done with the B&amp;W vs colour frame.  Clever technique.</td>', 'Excellent photo in general, but I especially like what you''ve done with the B&W vs colour frame.  Clever technique.', '2004-08-10 04:48:51.000000', NULL, 1),
(852121, 96109, 3087, '<td valign="top">What an evocative image! The reflections in the water really convey a hot sunny day which just calls out for a cooling dip of the feet. Not sure about the decision to go black and white - hard to tell without seeing the same image in colour. Composition works well, you have included just enough of the legs and I like the way they come into the frame from the respective lower corners. 9</td>', 'What an evocative image! The reflections in the water really convey a hot sunny day which just calls out for a cooling dip of the feet. Not sure about the decision to go black and white - hard to tell without seeing the same image in colour. Composition works well, you have included just enough of the legs and I like the way they come into the frame from the respective lower corners. 9', '2004-08-10 05:15:56.000000', NULL, 1),
(852122, 96091, 3087, '<td valign="top">A lovely idea and the shallow DOF definitely adds something. I am not keen on the ratio being quite so wide and short. I think it would feel more balanced if nearer to a more standard ratio. I understand that would require the text to be positioned a little differently or perhaps just a slightly different composition. Just my two pennies anyway. 9</td>', 'A lovely idea and the shallow DOF definitely adds something. I am not keen on the ratio being quite so wide and short. I think it would feel more balanced if nearer to a more standard ratio. I understand that would require the text to be positioned a little differently or perhaps just a slightly different composition. Just my two pennies anyway. 9', '2004-08-10 05:17:35.000000', NULL, 1),
(852123, 95368, 3087, '<td valign="top">Such a beautiful and simple image. I particularly like how understated but perfect the light is - low enough to only just bring out the details in the foreground cobbles but enough to make the pedestrian into a solid silhouette. Nicely composed too. 9</td>', 'Such a beautiful and simple image. I particularly like how understated but perfect the light is - low enough to only just bring out the details in the foreground cobbles but enough to make the pedestrian into a solid silhouette. Nicely composed too. 9', '2004-08-10 05:18:50.000000', NULL, 1),
(852127, 96314, 16301, '<td valign="top">Very good lighting, I like the plasticy feel to the feet. (8)</td>', 'Very good lighting, I like the plasticy feel to the feet. (8)', '2004-08-10 05:39:54.000000', NULL, 1),
(852129, 96522, 16301, '<td valign="top">Cool idea, I like the OOF shoes. B&amp;W works well with it. (8)</td>', 'Cool idea, I like the OOF shoes. B&W works well with it. (8)', '2004-08-10 05:41:08.000000', NULL, 1),
(852132, 95828, 16301, '<td valign="top">Nice idea, I like the high key look. How did it look with more darkness (to fit the mood)? (8)</td>', 'Nice idea, I like the high key look. How did it look with more darkness (to fit the mood)? (8)', '2004-08-10 05:42:41.000000', NULL, 1),
(852134, 96501, 16301, '<td valign="top">Nice idea, I like the soft colors in the photo. (8)</td>', 'Nice idea, I like the soft colors in the photo. (8)', '2004-08-10 05:44:27.000000', NULL, 1),
(852135, 96505, 16301, '<td valign="top">DUUUUDE! Very cool idea, well executed. (8)</td>', 'DUUUUDE! Very cool idea, well executed. (8)', '2004-08-10 05:45:33.000000', NULL, 1),
