INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(853089, 96338, 20115, '<td valign="top">This looks really creepy -- great idea.</td>', 'This looks really creepy -- great idea.', '2004-08-10 21:37:02.000000', NULL, 1),
(853091, 96534, 20115, '<td valign="top">much too dark</td>', 'much too dark', '2004-08-10 21:38:45.000000', NULL, 1),
(853095, 95827, 20115, '<td valign="top">This both sad and courageous for the people who actually travel this way--and for the shot as well.  For the shot I would have had more of the prosthetic visible (not too much) and perhaps have done it in B&amp;W.  You will no doubt receive many comments.</td>', 'This both sad and courageous for the people who actually travel this way--and for the shot as well.  For the shot I would have had more of the prosthetic visible (not too much) and perhaps have done it in B&W.  You will no doubt receive many comments.', '2004-08-10 21:44:14.000000', NULL, 1),
(853097, 96457, 20115, '<td valign="top">very interesting--putting the focus on what''s really happening here.  Very nice.</td>', 'very interesting--putting the focus on what''s really happening here.  Very nice.', '2004-08-10 21:45:46.000000', NULL, 1),
(853100, 95812, 20115, '<td valign="top">sweet, but too dark</td>', 'sweet, but too dark', '2004-08-10 21:47:19.000000', NULL, 1),
(853103, 95605, 20115, '<td valign="top">I would have cleaned up the feet a bit--a little healing in photoshop would have helped this shot.  Very nice otherwise.</td>', 'I would have cleaned up the feet a bit--a little healing in photoshop would have helped this shot.  Very nice otherwise.', '2004-08-10 21:48:39.000000', NULL, 1),
(853119, 95605, 20226, '<td valign="top">attractive</td>', 'attractive', '2004-08-10 22:06:07.000000', NULL, 1),
(853123, 96584, 24239, '<td valign="top">nice composition and just enough color. i like the symbolism of feet, without the feet.</td>', 'nice composition and just enough color. i like the symbolism of feet, without the feet.', '2004-08-10 22:08:30.000000', NULL, 1),
(853124, 96517, 24239, '<td valign="top">very sweet</td>', 'very sweet', '2004-08-10 22:08:50.000000', NULL, 1),
(853125, 95995, 24239, '<td valign="top">LOL, nice point of view</td>', 'LOL, nice point of view', '2004-08-10 22:09:20.000000', NULL, 1),
