INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(858737, 96465, 19322, '<td valign="top">Very n ice balance of color, and the slow shutter gives a real feel to the water on the feet.  Brings back memories.</td>', 'Very n ice balance of color, and the slow shutter gives a real feel to the water on the feet.  Brings back memories.', '2004-08-13 15:44:50.000000', NULL, 1),
(858742, 96510, 19322, '<td valign="top">Good use of selective de-saturation.  I would prefer the de-saturated area a little softer, I think.</td>', 'Good use of selective de-saturation.  I would prefer the de-saturated area a little softer, I think.', '2004-08-13 15:47:03.000000', NULL, 1),
(858744, 96022, 19322, '<td valign="top">Nicely done, but a bit of a "stretch" (no pun intended).</td>', 'Nicely done, but a bit of a "stretch" (no pun intended).', '2004-08-13 15:51:02.000000', NULL, 1),
(858754, 96571, 19322, '<td valign="top">Lighting is too harsh, needs more contrast (e.g darker background)</td>', 'Lighting is too harsh, needs more contrast (e.g darker background)', '2004-08-13 15:57:40.000000', NULL, 1),
(858757, 96609, 19322, '<td valign="top">The feet seem almost subordinate to the cross.</td>', 'The feet seem almost subordinate to the cross.', '2004-08-13 15:59:18.000000', NULL, 1),
(858765, 96504, 19322, '<td valign="top">I''d cut out the lower half of the picture.</td>', 'I''d cut out the lower half of the picture.', '2004-08-13 16:03:10.000000', NULL, 1),
(858771, 96556, 19322, '<td valign="top">Interesting shot and lighting.</td>', 'Interesting shot and lighting.', '2004-08-13 16:06:36.000000', NULL, 1),
(858775, 95448, 19322, '<td valign="top">I like the idea but think the feet should figure more prominently, somehow.</td>', 'I like the idea but think the feet should figure more prominently, somehow.', '2004-08-13 16:08:46.000000', NULL, 1),
(858780, 96604, 19322, '<td valign="top">The celing light and the celiling/wall angles are distracting.</td>', 'The celing light and the celiling/wall angles are distracting.', '2004-08-13 16:11:56.000000', NULL, 1),
(858790, 95589, 19322, '<td valign="top">Well thought out, and pleasing.</td>', 'Well thought out, and pleasing.', '2004-08-13 16:16:58.000000', NULL, 1),
(858794, 96505, 22734, '<td valign="top">Voted earlier, returning for comments.<br/> <br/>Very impressive. Action is very well displayed. The shoe texture is great and the composition and cropping excellent. Bumping from 5 to 6.</td>', 'Voted earlier, returning for comments. Very impressive. Action is very well displayed. The shoe texture is great and the composition and cropping excellent. Bumping from 5 to 6.', '2004-08-13 16:19:08.000000', NULL, 1),
(858796, 96291, 22734, '<td valign="top">Very creative use of soil with that cool martain color shift. Good comp and good use of negative space. Bumping from 5 to 6.</td>', 'Very creative use of soil with that cool martain color shift. Good comp and good use of negative space. Bumping from 5 to 6.', '2004-08-13 16:22:29.000000', NULL, 1),
(858799, 96459, 19322, '<td valign="top">The feet are only a minor feature here, so that I feel the need to rate the pciture down.</td>', 'The feet are only a minor feature here, so that I feel the need to rate the pciture down.', '2004-08-13 16:26:30.000000', NULL, 1),
(858803, 96063, 8860, '<td valign="top">This is doubtless an excellent photo - rich in tonal range and texture, full of detail and well composed. The only flaw in my view, is that these feet are bereft of the very context that led them to be this way. <br/> <br/>For the cynics this is a staged shot reliant on the title to suggest it''s a genuine subject - and the trainers/sneakers appear to be pretty decent apart from some carefully placed, crisply cut holes.<br/> <br/>For those who aren''t cynical and go for DPC aesthetic, it''s a blue ribbon. <br/> <br/>For me - I''m between the two. It''s not perfect because of the lack of context which would add so much gravitas - of course it might still not satisfy cynics, but there would be more of a statement for its case.</td>', 'This is doubtless an excellent photo - rich in tonal range and texture, full of detail and well composed. The only flaw in my view, is that these feet are bereft of the very context that led them to be this way.  For the cynics this is a staged shot reliant on the title to suggest it''s a genuine subject - and the trainers/sneakers appear to be pretty decent apart from some carefully placed, crisply cut holes. For those who aren''t cynical and go for DPC aesthetic, it''s a blue ribbon.  For me - I''m between the two. It''s not perfect because of the lack of context which would add so much gravitas - of course it might still not satisfy cynics, but there would be more of a statement for its case.', '2004-08-13 16:29:38.000000', NULL, 1),
(858804, 95589, 8860, '<td valign="top">I took some shots like this (I''ll upload some after) but this is very good with some lovely lighting and tone around the feet. <br/> <br/>My one bug is the people''s stance. I''d much rather they were not looking down and we were left with just the shapes. The arrangement of the feet is also a little awkward and an off-centre composition would assist the light, airy feel in the shot.</td>', 'I took some shots like this (I''ll upload some after) but this is very good with some lovely lighting and tone around the feet.  My one bug is the people''s stance. I''d much rather they were not looking down and we were left with just the shapes. The arrangement of the feet is also a little awkward and an off-centre composition would assist the light, airy feel in the shot.', '2004-08-13 16:30:16.000000', NULL, 1),
(858805, 95630, 22734, '<td valign="top"><br/>Voted earlier, returning for comments.<br/> <br/>This is a very nice study illustrating brotherly love. The twist to use the color nail polish on both advances and raises the value if this image. Bumping from 5 to 7</td>', 'Voted earlier, returning for comments. This is a very nice study illustrating brotherly love. The twist to use the color nail polish on both advances and raises the value if this image. Bumping from 5 to 7', '2004-08-13 16:30:48.000000', NULL, 1),
(858806, 96507, 8860, '<td valign="top">Tasty looking feet! Excellent texture - you did well to get so close. They look so reptilian when you don''t see the owner, very reminiscent of dinosaurs. Good take.</td>', 'Tasty looking feet! Excellent texture - you did well to get so close. They look so reptilian when you don''t see the owner, very reminiscent of dinosaurs. Good take.', '2004-08-13 16:30:58.000000', NULL, 1),
