INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(860530, 96605, 2158, '<td valign="top">Nice shot, but in serious need of noise reduction.  Neatimage would do a good job on this one.</td>', 'Nice shot, but in serious need of noise reduction.  Neatimage would do a good job on this one.', '2004-08-15 19:29:16.000000', NULL, 1),
(860556, 95589, 22734, '<td valign="top">Possibly one of the most creative shots in this challenge and certainly my favorite.<br/>Because it comes off as a graphical represenrarion I wonder if something else could have been done to strengthened the final outcome. Regardless, it remains a very cool effect and enough charm even as it is with the light tint values. Bumping image from 5 to 8<br/><br/><i>Message edited by author 2004-08-16 01:11:34.</i></td>', 'Possibly one of the most creative shots in this challenge and certainly my favorite.Because it comes off as a graphical represenrarion I wonder if something else could have been done to strengthened the final outcome. Regardless, it remains a very cool effect and enough charm even as it is with the light tint values. Bumping image from 5 to 8', '2004-08-15 20:07:53.000000', '2004-08-16 02:11:34.000000', 1),
(860558, 95688, 22734, '<td valign="top">Voted earlier, returning for comments:<br/> <br/>A very nice idea, however, I would raised the angle of view higher right below the bowl which would create the suggestion of sitting on bowl. Bumping image from 5 to 6</td>', 'Voted earlier, returning for comments: A very nice idea, however, I would raised the angle of view higher right below the bowl which would create the suggestion of sitting on bowl. Bumping image from 5 to 6', '2004-08-15 20:10:42.000000', NULL, 1),
